// Hand-written. Not generated by Speakeasy.
//
// Keeps a client's certificate subject type switchable.
//
// Authlete accepts exactly one way of identifying a client's certificate, and
// rejects a request naming two with A032216. The five attributes are
// Optional+Computed, so removing one from configuration does not clear it:
// Terraform keeps the last known value and the provider sends it alongside the
// new one. Switching therefore fails on every apply, and setting the old
// attribute to "" does not help -- an empty string still counts as naming it.
// The only escape is replacing the client, which changes its client_id and
// breaks every application using it.
//
// This clears an attribute that configuration no longer names, when
// configuration names a different one. Terraform shows the clearing in the plan
// like any other change, so nothing happens silently.
//
// Deliberately narrow. It acts only when configuration is unambiguous: one
// subject type named, the rest absent. Two named at once is the practitioner's
// ambiguity to resolve, not ours to guess at, and is rejected at plan time by
// the validator in mtls_subject_validator.go.
package planmodifiers

import (
	"context"

	"github.com/hashicorp/terraform-plugin-framework/path"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/planmodifier"
	"github.com/hashicorp/terraform-plugin-framework/types"
)

// MTLSSubjectAttributes are the mutually exclusive certificate subject types.
// Exported so the validator and the tests share one definition.
var MTLSSubjectAttributes = []string{
	"tls_client_auth_subject_dn",
	"tls_client_auth_san_dns",
	"tls_client_auth_san_email",
	"tls_client_auth_san_ip",
	"tls_client_auth_san_uri",
}

// ClearSupersededSubjectType returns a plan modifier for one of the five
// attributes, which clears it when configuration names a different one.
func ClearSupersededSubjectType(self string) planmodifier.String {
	return clearSupersededSubjectType{self: self}
}

type clearSupersededSubjectType struct{ self string }

func (m clearSupersededSubjectType) Description(_ context.Context) string {
	return "clears this certificate subject type when configuration names a different one, " +
		"since Authlete accepts exactly one"
}

func (m clearSupersededSubjectType) MarkdownDescription(ctx context.Context) string {
	return m.Description(ctx)
}

func (m clearSupersededSubjectType) PlanModifyString(ctx context.Context, req planmodifier.StringRequest, resp *planmodifier.StringResponse) {
	// Creation has no prior value to supersede.
	if req.State.Raw.IsNull() {
		return
	}

	// Configuration still names this one, so it is not superseded.
	var self types.String
	if diags := req.Config.GetAttribute(ctx, path.Root(m.self), &self); diags.HasError() {
		return
	}
	if !self.IsNull() && self.ValueString() != "" {
		return
	}

	// Nothing to clear.
	if req.StateValue.IsNull() || req.StateValue.ValueString() == "" {
		return
	}

	for _, other := range MTLSSubjectAttributes {
		if other == m.self {
			continue
		}
		var v types.String
		if diags := req.Config.GetAttribute(ctx, path.Root(other), &v); diags.HasError() {
			continue
		}
		if !v.IsNull() && v.ValueString() != "" {
			// Null, not empty: Authlete counts an empty string as naming this
			// subject type, so it must be absent from the request rather than
			// present and blank. The generated conversion omits a null scalar.
			resp.PlanValue = types.StringNull()
			return
		}
	}
}
